/**
 * A GitHub Action to notify a channel on Discord using Discord webhooks.
 * See action.yml for the details on the inputs.
 *
 */

import { getRandomDadJoke, getCat } from "./fun";

import * as core from "@actions/core";

import { EmbedBuilder, WebhookClient, MessageFlagsBitField, AttachmentBuilder } from "discord.js";

import * as defaults from "./defaults";
import {
  truncateStringIfNeeded,
  sanitizeUsername,
  processIfNeeded
} from "./strutil";

/**
 * This is the main code for the GitHub Action
 *
 * @returns { undefined }
 */
export async function run(mockedWebhookClient = null) {
  try {
    let webhookUrl = core.getInput("webhookUrl");
    if (typeof webhookUrl === "undefined" || !webhookUrl) {
      core.setFailed(
        "The webhookUrl was not provided. For security reasons the secret URL must be provided " +
        "in the action yaml using a context expression and can not be read as a default.\n" +
        "DISCORD NOTIFICATION NOT SENT"
      );
      return;
    }
    webhookUrl = webhookUrl.replace("/github", "");

    // goes in message
    const username = sanitizeUsername(
      core.getInput("username") || defaults.username
    );
    const avatarUrl =
      truncateStringIfNeeded(core.getInput("avatarUrl")) || defaults.avatarUrl;
    const text =
      truncateStringIfNeeded(processIfNeeded(core.getInput("text") || ""));
    const flags = core.getInput("flags") || "";

    // goes in embed in message
    const severity = core.getInput("severity") || "none";
    const title = core.getInput("title") || "";
    const description = core.getInput("description") || "";
    const color = core.getInput("color");
    const linkUrl = core.getInput("linkUrl");
    const fieldsInput = core.getInput("fields") || "[]";
    const thumbnailUrl = core.getInput("thumbnailUrl");
    
    const dadJoke = await getRandomDadJoke();

    const addDadJoke = true;
    const addCat = true;

    let fields = [];
    try {
      fields = JSON.parse(fieldsInput);
      if (!Array.isArray(fields)) {
        throw new Error("fields is not an array");
      }
      if (fields.length > 25) {
        core.warning("Discord only supports up to 25 fields. Extra fields ignored.");
        fields = fields.slice(0, 25);
      }
      for (const field of fields) {
        if (typeof field.name !== "string" || typeof field.value !== "string") {
          throw new Error("field name or value is not a string");
        }
        field.name = truncateStringIfNeeded(processIfNeeded(field.name), 256);
        field.value = truncateStringIfNeeded(processIfNeeded(field.value), 1024);
        if (field.inline !== true) {
          field.inline = false;
        }
      }
    } catch (e) {
      core.warning(
        `The fields input is not valid JSON or is not an array of objects with name and value strings. Error: ${e.message}\nNo fields will be sent.`
      );
      fields = [];
    }

    let webhookClient;
    /* istanbul ignore next */
    if (mockedWebhookClient) {
      console.log("WARNING: Using mockedWebhookClient (unit testing only)");
      webhookClient = mockedWebhookClient;
    } else {
      webhookClient = new WebhookClient({ url: webhookUrl });
    }

    let msg;
    if (severity === "none") {
      msg = {
        username: username,
        avatarURL: avatarUrl
      };
    } else {
      core.debug(`Creating embed with severity ${severity}`);
      core.debug(JSON.stringify(fields));
      
      const embed = new EmbedBuilder()
        .setTitle(
          truncateStringIfNeeded(title) || null
        )
        .setURL(linkUrl || null)
        .setColor(color || defaults.colors[severity])
        .addFields(fields)
        .setDescription(
          truncateStringIfNeeded(processIfNeeded((description))) || null
        )
        .setFooter({
          text:
            truncateStringIfNeeded(addDadJoke ? dadJoke : "") ||
            null
        })
        .setThumbnail(thumbnailUrl || null)
        .setImage(addCat ? "attachment://cat.jpg" : null)
        .setTimestamp();

      // Log the embed object for debugging
      core.debug(`Embed object: ${JSON.stringify(embed.toJSON())}`);
      msg = {
        username: username,
        avatarURL: avatarUrl,
        embeds: [embed]
      };
    }

    if (addCat) {
        const catUrl = await getCat();
        core.debug(`Cat URL: ${catUrl}`);
        const cat = new AttachmentBuilder(catUrl || "", { name: "cat.jpg" });
        msg.files = [cat];
    }

    if (text) msg.content = text;

    if (flags !== "") {
      msg.flags = 0;
      if (/SuppressNotifications/.test(flags)) {
        msg.flags |= MessageFlagsBitField.Flags.SuppressNotifications;
      }
      if (/SuppressEmbeds/.test(flags)) {
        msg.flags |= MessageFlagsBitField.Flags.SuppressEmbeds;
      }
      if (/IsComponentsV2/.test(flags)) {
        msg.flags |= MessageFlagsBitField.Flags.IsComponentsV2;
      }
    }

    await webhookClient.send(msg);

  } catch (error) {
    // not so sure the workflow should show an error just because the notification failed
    core.notice(error);
  }

  return;
}
